import { servicenowHtmlPlugin } from "../../src/vite/html";

type PluginRecord = Record<string, any>;

// Stand-in for src/ui-page: it serialises the page, hands it to transformHtml,
// then emits the result with this.emitFile — the same order as the real plugin.
const mockUiPage: {
  html: string;
  transformHtml?: (html: string, fileName: string) => string;
} = { html: "<html><head><title>Test</title></head><body></body></html>" };

jest.mock("../../src/index", () => ({
  uiPage: jest.fn(
    (opts: { transformHtml?: (html: string, fileName: string) => string }) => {
      mockUiPage.transformHtml = opts.transformHtml;
      return {
        options: jest.fn().mockReturnValue({ input: "mocked" }),
        buildStart: jest.fn(),
        generateBundle: jest.fn(function (this: {
          emitFile?: (file: Record<string, unknown>) => string;
        }) {
          const source = mockUiPage.transformHtml
            ? mockUiPage.transformHtml(mockUiPage.html, "index.html")
            : mockUiPage.html;
          this.emitFile?.({
            type: "asset",
            fileName: "index.html",
            source,
          });
        }),
      };
    },
  ),
}));

const simulateMode = (plugin: PluginRecord, command: "serve" | "build") => {
  plugin.configResolved({ command });
};

const makeChunk = (
  fileName: string,
  opts: {
    isEntry?: boolean;
    importedCss?: string[];
    importedCssUrls?: Map<string, string>;
  } = {},
) => ({
  type: "chunk" as const,
  fileName,
  isEntry: opts.isEntry ?? false,
  code: "",
  viteMetadata: {
    importedCss: new Set(opts.importedCss ?? []),
    importedCssUrls: opts.importedCssUrls,
  },
});

const HTML = mockUiPage.html;

// Rollup adds assets emitted during generateBundle to the same `bundle` object
// the hook was handed; Rolldown (the bundler behind Vite 8) does not. Both are
// exercised so the plugin can never regress into depending on that difference.
type EmitFlavor = "rollup" | "rolldown";
const EMIT_FLAVORS: EmitFlavor[] = ["rollup", "rolldown"];

const runGenerateBundle = (
  plugin: PluginRecord,
  bundle: Record<string, any>,
  flavor: EmitFlavor,
): Array<{ fileName: string; source: string }> => {
  const emitted: Array<{ fileName: string; source: string }> = [];
  const ctx = {
    emitFile(file: { fileName: string; source: string }) {
      emitted.push({ fileName: file.fileName, source: file.source });
      if (flavor === "rollup") {
        bundle[file.fileName] = { type: "asset", ...file };
      }
      return "ref";
    },
  };
  plugin.generateBundle.call(ctx, {}, bundle, false);
  return emitted;
};

describe("servicenowHtmlPlugin", () => {
  const defaultOptions = {
    rootDir: "/app",
  };

  describe("transformIndexHtml", () => {
    test("replaces sdk:now-ux-globals tag in serve mode", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "serve");

      const html = "<html><head><sdk:now-ux-globals /></head></html>";
      const result = plugin.transformIndexHtml(html);
      expect(result).toContain('<script type="module">');
      expect(result).toContain("library-uxf/index.jsdbx");
      expect(result).not.toContain("sdk:now-ux-globals");
    });

    test("replaces self-closing sdk:now-ux-globals with closing tag", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "serve");

      const html =
        "<html><head><sdk:now-ux-globals></sdk:now-ux-globals></head></html>";
      const result = plugin.transformIndexHtml(html);
      expect(result).toContain('<script type="module">');
      expect(result).not.toContain("sdk:now-ux-globals");
    });

    test("returns html unchanged in build mode", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "build");

      const html = "<html><head><sdk:now-ux-globals /></head></html>";
      const result = plugin.transformIndexHtml(html);
      expect(result).toBe(html);
    });
  });

  describe("build mode delegation", () => {
    test("delegates options to uiPage in build mode", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "build");

      const result = plugin.options.call({}, { input: "original" });
      expect(result).toEqual({ input: "mocked" });
    });

    test("skips options delegation in serve mode", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "serve");

      const input = { input: "original" };
      const result = plugin.options.call({}, input);
      expect(result).toBe(input);
    });

    test("delegates buildStart to uiPage in build mode", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "build");

      expect(() => plugin.buildStart.call({})).not.toThrow();
    });

    test("skips buildStart in serve mode", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "serve");

      expect(() => plugin.buildStart.call({})).not.toThrow();
    });

    test("delegates generateBundle to uiPage in build mode", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "build");

      expect(() => plugin.generateBundle.call({}, {}, {}, false)).not.toThrow();
    });

    test("skips generateBundle in serve mode", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "serve");

      expect(() => plugin.generateBundle.call({}, {}, {}, false)).not.toThrow();
    });
  });

  describe.each(EMIT_FLAVORS)("CSS link injection (%s emitFile)", (flavor) => {
    test("injects uxta link for entry chunk CSS", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "build");

      const bundle: Record<string, any> = {
        "main.jsdbx": makeChunk("main.jsdbx", {
          isEntry: true,
          importedCss: ["main.css"],
          importedCssUrls: new Map([["main.css", "/uxta/abc123.assetx"]]),
        }),
      };

      const emitted = runGenerateBundle(plugin, bundle, flavor);
      expect(emitted).toHaveLength(1);
      expect(emitted[0].source).toContain('href="/uxta/abc123.assetx"');
      expect(emitted[0].source).toContain('rel="stylesheet"');
    });

    test("does not inject link for lazy chunk CSS", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "build");

      const bundle: Record<string, any> = {
        "main.jsdbx": makeChunk("main.jsdbx", {
          isEntry: true,
          importedCss: ["main.css"],
          importedCssUrls: new Map([["main.css", "/uxta/main-id.assetx"]]),
        }),
        "IncidentForm.jsdbx": makeChunk("IncidentForm.jsdbx", {
          isEntry: false,
          importedCss: ["IncidentForm.css"],
          importedCssUrls: new Map([
            ["IncidentForm.css", "/uxta/form-id.assetx"],
          ]),
        }),
      };

      const emitted = runGenerateBundle(plugin, bundle, flavor);
      expect(emitted[0].source).toContain('href="/uxta/main-id.assetx"');
      expect(emitted[0].source).not.toContain("form-id");
    });

    test("injects the link exactly once", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "build");

      const bundle: Record<string, any> = {
        "main.jsdbx": makeChunk("main.jsdbx", {
          isEntry: true,
          importedCss: ["main.css"],
          importedCssUrls: new Map([["main.css", "/uxta/abc123.assetx"]]),
        }),
      };

      const emitted = runGenerateBundle(plugin, bundle, flavor);
      expect(emitted[0].source.match(/uxta\/abc123\.assetx/g)).toHaveLength(1);
    });

    test("does not inject link when no entry CSS", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "build");

      const bundle: Record<string, any> = {
        "main.jsdbx": makeChunk("main.jsdbx", {
          isEntry: true,
          importedCss: [],
        }),
      };

      const emitted = runGenerateBundle(plugin, bundle, flavor);
      expect(emitted[0].source).toBe(HTML);
    });

    test("does not carry entry CSS over into a later build", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "build");

      const withCss: Record<string, any> = {
        "main.jsdbx": makeChunk("main.jsdbx", {
          isEntry: true,
          importedCss: ["main.css"],
          importedCssUrls: new Map([["main.css", "/uxta/abc123.assetx"]]),
        }),
      };
      runGenerateBundle(plugin, withCss, flavor);

      const withoutCss: Record<string, any> = {
        "main.jsdbx": makeChunk("main.jsdbx", { isEntry: true }),
      };
      const emitted = runGenerateBundle(plugin, withoutCss, flavor);
      expect(emitted[0].source).toBe(HTML);
    });

    test("skips in serve mode", () => {
      const plugin = servicenowHtmlPlugin(defaultOptions) as PluginRecord;
      simulateMode(plugin, "serve");

      const bundle: Record<string, any> = {
        "main.jsdbx": makeChunk("main.jsdbx", {
          isEntry: true,
          importedCss: ["main.css"],
          importedCssUrls: new Map([["main.css", "/uxta/abc123.assetx"]]),
        }),
      };

      const emitted = runGenerateBundle(plugin, bundle, flavor);
      expect(emitted).toHaveLength(0);
    });
  });
});
